1	<?php
2	defined( 'WP_UNINSTALL_PLUGIN' ) || exit;
3	
4	global $wpdb;
5	
6	// Delete Imagify options.
7	delete_site_option( 'imagify_settings' );
8	delete_site_option( 'imagify_old_version' );
9	delete_site_option( 'imagify_files_db_version' );
10	delete_site_option( 'imagify_folders_db_version' );
11	delete_option( 'imagify_data' );
12	delete_option( 'ngg_imagify_data_db_version' );
13	delete_option( $wpdb->prefix . 'ngg_imagify_data_db_version' );
14	
15	// Delete all transients.
16	delete_site_transient( 'imagify_activation' );
17	delete_site_transient( 'imagify_check_licence_1' );
18	delete_site_transient( 'imagify_check_api_version' );
19	delete_site_transient( 'imagify_user' );
20	delete_site_transient( 'imagify_themes_plugins_to_sync' );
21	delete_site_transient( 'do_imagify_rating_cron' );
22	delete_site_transient( 'imagify_seen_rating_notice' );
23	delete_site_transient( 'imagify_user_images_count' );
24	delete_transient( 'imagify_activation' );
25	delete_transient( 'imagify_bulk_optimization_level' );
26	delete_transient( 'imagify_bulk_optimization_infos' );
27	delete_transient( 'imagify_large_library' );
28	delete_transient( 'imagify_max_image_size' );
29	delete_transient( 'imagify_user' );
30	delete_transient( 'imagify_stat_without_next_gen' );
31	delete_transient( 'imagify_bulk_optimization_result' );
32	delete_transient( 'imagify_attachments_number_modal' );
33	delete_transient( 'imagify_user_cache' );
34	
35	// Delete transients.
36	$transients = implode(
37		'" OR option_name LIKE "',
38		[
39			'\_transient\_%imagify-auto-optimize-%',
40			'\_transient\_%imagify\_rpc\_%',
41			'\_transient\_imagify\_%\_process\_locked',
42			'\_site\_transient\_imagify\_%\_process\_lock%',
43		]
44	);
45	$wpdb->query( "DELETE from $wpdb->options WHERE option_name LIKE \"$transients\"" ); // WPCS: unprepared SQL ok.
