350		 * This is used by the bulk optimization page.
351		 *
352		 * @since 1.9
353		 *
354		 * @param  int    $media_id The media ID.
355		 * @param  string $context  The context.
356		 * @param  int    $level    The optimization level.
357		 *
358		 * @return bool|WP_Error True if successfully launched. A \WP_Error instance on failure.
359		 */
360		private function force_optimize( int $media_id, string $context, int $level ) {
361			if ( ! $this->can_optimize() ) {
362				$this->decrease_counter( $context );
363	
364				return false;
365			}
366	
367			$process = imagify_get_optimization_process( $media_id, $context );
368			$data    = $process->get_data();
369	
370			// Restore before re-optimizing.
371			if ( $data->is_optimized() ) {
372				$result = $process->restore();
373	
374				if ( is_wp_error( $result ) ) {
375					$this->decrease_counter( $context );
376	
377					// Return an error message.
378					return $result;
379				}
380			}
381	
382			return $process->optimize( $level );
383		}
