281			}
282	
283			if ( isset( $item['error'] ) && ! is_wp_error( $item['error'] ) ) {
284				unset( $item['error'] );
285			}
286	
287			if ( isset( $item['data']['hook_suffix'] ) && ! is_string( $item['data']['hook_suffix'] ) ) {
